contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmount);

        // observe balance before
        uint balBefore = address(c).balance;

        bool reverted;
        c.go{value: sendAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;

        // General rule: after calling go (whether it reverts or not), C's balance is not greater than before
        assert(balAfter <= balBefore);
    }
    receive() external payable {}
}

