// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    B c;

    function setUp() public {
        c = new B();
    }

    function _run(uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.go{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        assertTrue(balAfter <= balBefore);
    }

    function testFuzz_run(uint256 sendAmount) public {
        _run(sendAmount);
    }

    receive() external payable {}
}
